	@Test
	void localJoinPreservesInputAndRemoteMultiplicity() throws Exception {
		Harness harness = new Harness();
		Value first = VF.createLiteral("first");
		Value second = VF.createLiteral("second");
		Value repeatedLabel = VF.createLiteral("repeat");
		List<BindingSet> inputs = new ArrayList<>();
		for (int i = 0; i < 14; i++) {
			inputs.add(binding("x", first, "input", VF.createLiteral("input-" + i)));
		}
		for (int i = 14; i < 16; i++) {
			inputs.add(binding("x", second, "input", VF.createLiteral("input-" + i)));
		}
		TupleQueryResult remote = tupleResult(List.of(
				binding("x", first, "label", repeatedLabel),
				binding("x", first, "label", repeatedLabel),
				binding("x", second, "label", VF.createLiteral("once"))));
		when(harness.query.evaluate()).thenReturn(remote);

		Service service = service(statement("x", "label"), "?x <urn:test:p> ?label", false);
		List<BindingSet> actual = evaluate(harness.service, service, inputs);

		assertEquals(30, actual.size());
		Map<String, Long> actualBag = actual.stream()
				.collect(Collectors.groupingBy(
						row -> row.getValue("input").stringValue() + "/" + row.getValue("label").stringValue(),
						Collectors.counting()));
		Map<String, Long> expectedBag = new HashMap<>();
		for (int i = 0; i < 14; i++) {
			expectedBag.put("input-" + i + "/repeat", 2L);
		}
		for (int i = 14; i < 16; i++) {
			expectedBag.put("input-" + i + "/once", 1L);
		}
		assertEquals(expectedBag, actualBag);
		verify(harness.query, times(1)).evaluate();
		verify(remote).close();
		verify(harness.connection).close();
	}

